using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;
using Xunit;

public class LedgerIssue2297
{
    [Fact]
    public async Task GeneratedSources_IncludeExcludeFromCodeCoverageAttribute()
    {
        var net80Refs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var mpRefs = ReferencesHelper.GetReferences(ReferencesSet.MessagePack);
        var references = net80Refs.AddRange(mpRefs);

        string source = """
using MessagePack;

namespace TestNamespace
{
    [MessagePackObject]
    public class SampleClass
    {
        [Key(0)]
        public int Id { get; set; }

        [Key(1)]
        public string? Name { get; set; }
    }
}
""";

        CSharpCompilation compilation = CSharpCompilation.Create(
            "TestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest)) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult runResult = driver.GetRunResult();

        Assert.Empty(generatorDiagnostics);
        var generatedSources = runResult.Results.SelectMany(r => r.GeneratedSources).ToList();
        Assert.NotEmpty(generatedSources);

        foreach (var generatedSource in generatedSources)
        {
            string generatedText = generatedSource.SourceText.ToString();
            Assert.Contains("ExcludeFromCodeCoverage", generatedText);
        }
    }
}
